// Seed 京都府 · 食類 條目 → public.japan_entries(Sprint 14.1)
//
// 京都食文化深度極高,Phase 1 目標 ~90 筆,涵蓋:
//   - kyo_kaiseki(京懷石/料亭):瓢亭・菊乃井・和久傳・桜田・未在 等老舗 + 三星店
//   - shojin_ryori(精進料理/湯豆腐):順正・奥丹・大徳寺一久・嵯峨豆腐森嘉
//   - obanzai(京おばんざい):八千代・澤井醤油・伊勢屋
//   - kyo_zushi(京壽司):いづう・いづ重・末廣
//   - cafe_wagashi(京菓子・茶寮):虎屋・笹屋伊織・鶴屋吉信・出町ふたば・茶寮都路里
//   - 京うどん・京蕎麦:本家尾張屋・河道屋・権太呂・山元麺蔵
//   - 老舗喫茶:イノダコーヒ・進々堂・フランソア・スマート珈琲
//   - 京都ラーメン:第一旭・新福菜館・ますたに・天下一品総本店
//   - 老舗洋食:グリル小宝・東洋亭・菊水
//   - brewery 伏見酒蔵:月桂冠大倉・黄桜・玉乃光
//
// 設計原則(per feedback_usefulness_over_traffic.md):
//   超級深度。中文圈策展稀缺資訊優先 — 創業年代、御用達歷史、季節推奨、文化脈絡。
//   每筆 content_md 12-18 行(比北海道 10 行更深)。
//
// 資料源分層(L1=Wikipedia/官方,L2=普遍知識):
//   L1 確認:虎屋(1520)・笹屋伊織(1716 弘法どら焼)・本家尾張屋(1465)・川端道喜(室町幕府御用達)・
//   一保堂(1717)・聖護院八つ橋(1689)・出町ふたば(1899)・二軒茶屋中村楼(1502 文亀)・
//   月桂冠(1637)・瓢亭(1837)・菊乃井(1912)・順正(1839 創業の南禅寺豆腐)・
//   イノダコーヒ(1940)・進々堂(1913)・フランソア(1934)・スマート珈琲店(1932)・
//   第一旭(1950)・新福菜館(1938)
//
// Usage:
//   npm run seed:japan-kyoto-food:dry
//   npm run seed:japan-kyoto-food

