      "享保 2 年(1717)創業、308 年余りの京都茶舗最高峰。**京都府茶業会議所・宇治茶代表**、皇室御用達でもある宇治茶専門店。寺町通の本店は江戸期町家造、隣接「嘉木」茶寮で抹茶を客が自分で点てる体験ができる。煎茶・玉露・抹茶・玄米茶・ほうじ茶を 30 種以上を扱い、品質・価格幅広い。海外進出(NY・パリ)で日本茶ブームの先鞭。",
