      "- 地址:京都市中京区寺町通二条上ル(地下鉄東西線「京都市役所前」駅徒歩 5 分)\n- 創業:享保 2 年(1717)— 江戸中期、近江商人由来\n- 営業:店舗 10:00-18:00 / 喫茶室「嘉木」10:00-17:00(LO 16:30)\n- 公休:無休\n- 招牌:玉露「天下一」40g ¥4,800・抹茶「初昔」40g ¥3,200・煎茶「玉露入り 八重桜」100g ¥1,500\n- **嘉木**(かぼく)茶寮:本店併設、「客自身で抹茶を点てる」体験(¥1,500)が特色\n- 茶種類:玉露 8 種・煎茶 12 種・抹茶 15 種・玄米茶 5 種・ほうじ茶 6 種\n- 宇治直送:契約農家からの宇治茶、毎週入荷の鮮度管理\n- 皇室御用達:大正期から、現在も献上\n- 文化人:北大路魯山人・志賀直哉・谷崎潤一郎の馴染\n- 国際展開:NY 5 番街(2014)・パリ(2018)、日本茶 cafe ブームの基礎を築いた\n- 茶器:茶筅・茶杓・棗・茶碗を販売、初心者向けセット ¥4,400-9,900\n- 体験予約:嘉木は 1 週間前予約推奨、英語対応可\n- 寺町通:本店周辺は古書店・骨董店・茶道具店が並ぶ歴史商店街、半日散策可\n- 京都駅から:地下鉄烏丸線「四条」乗換東西線「京都市役所前」(計 15 分)\n- 価格帯:茶葉 ¥1,200-15,000 / 茶寮体験 ¥1,500\n- 2026-04 人工查核(一保堂官網)",
