    title_zh: "いづう",
    title_ja: "いづう",
    romaji: "Izuu",
    summary_zh:
      "天明元年(1781)創業、240 年余の**京都鯖寿司の元祖**。江戸期の御所御用達、宮廷料理人系譜から派生した京寿司司。若狭湾の鯖を一塩 + 米酢で熟成 → 棒状に成形し笹の葉で包む独特技法。日持ちのする「祭りの保存寿司」を芸術にまで高めた店、現当主は 10 代目。祇園切通しの本店は江戸期町家、夜は祇園街芸者・舞妓の差し入れの定番。",
    content_md:
      "- 地址:京都市東山区祇園町切通シ南北上ル八坂新地清本町367(京阪「祇園四条」駅徒歩 6 分)\n- 創業:天明元年(1781)— 御所御用達の鯖寿司司として開業\n- 営業:11:00-22:00(LO 21:30)\n- 公休:火曜\n- 招牌:**鯖姿寿司 1 本 8 切れ ¥4,500**・鯛箱寿司 ¥3,800・盛合せ ¥6,500\n- 「鯖姿寿司」:1 本の鯖を笹で包んだ棒寿司、江戸期からの「祭り寿司」を継承\n- 若狭鯖:京都に最も近い若狭湾(福井県)の鯖を「鯖街道」経由で運んだ伝統\n- 「鯖街道」(さばかいどう):若狭湾→若狭街道→京都への魚の運搬路、室町期から確立\n- 製法:鯖を 1 日塩・米酢で締め、シャリを巻き、笹で包む。30 時間以上の熟成\n- 賞味期限:作りたてから 36 時間、お土産としても 1 泊可\n- 当主:10 代目佐々木勝悟氏(2018 年襲名)、メディア出演多数\n- 祇園・先斗町:芸舞妓・お茶屋からの注文が多い、京都の祭り・お見舞いの定番贈答\n- 茶寮併設:本店 2 階で寿司 + 抹茶 + 香の物 ¥4,800\n- 国際:JR 西日本・JAL 国際線・伊勢丹新宿で取扱\n- 京都駅から:バス 206 系統「祇園」徒歩 6 分(計 20 分)\n- 価格帯:¥3,800-15,000、本格お土産は ¥4,500-9,000\n- 2026-04 人工查核(いづう官網)",
