    summary_zh:
      "安政 3 年(1856)創業、170 年。**「阿闍梨餅」**は比叡山延暦寺の千日回峰行(阿闍梨)から命名された京都銘菓、半生菓子の代表格。柔らかな餅生地に丹波大納言の粒あんを包んだシンプルな構成、しっとりもちもちの食感が癖になる。本店は北白川、京都市民の日常の手土産・親戚への贈答の定番。",
    content_md:
      "- 地址:京都市左京区鞠小路通今出川上ル(京阪「出町柳」駅徒歩 12 分)\n- 創業:安政 3 年(1856)\n- 営業:9:00-18:00\n- 公休:水曜\n- 招牌:**阿闍梨餅** 1 個 ¥130・5 個 ¥720・10 個 ¥1,400・京納言(羊羹)\n- 「阿闍梨餅」:比叡山千日回峰行の修行僧「阿闍梨」が被る網代笠の形を模した\n- 比叡山:店から見える比叡山延暦寺との霊的繋がり、信仰の対象から命名\n- 製法:餅粉・砂糖・卵・蜂蜜を捏ねた生地に丹波大納言粒あんを包み焼く、半生菓子\n- 賞味期限:5 日間、お土産にも対応\n- 売れ筋:1 日約 5 万個、京都駅・伊勢丹・大丸・三越でも取扱\n- 大正・昭和の文豪:谷崎潤一郎・志賀直哉が手土産に愛用\n- 観光連動:京都駅 ASTY 京都・京都伊勢丹で買える、わざわざ本店行かずとも入手可\n- 京都駅から:バス 17 系統「百万遍」徒歩 8 分(計 30 分)\n- 価格帯:¥130-2,800、お土産には 10 個入 ¥1,400 が定番\n- 2026-04 人工查核(満月官網)",
