      "寛永 14 年(1637)創業、**約 390 年の日本最古級酒造**(2024 年で 387 年目)。伏見「月桂冠」本社が 1909 年酒蔵を改装、酒造りの歴史と工程を見学できる博物館に。京都伏見の地下水「ご神水」(伏水)を使った酒造り、明治期の機械化以前の手作業道具・桶・杉樽を展示。試飲(3 種、入館料込 ¥600)で月桂冠の現役商品を体験。",
