    category: "food",
    sub_type: "local_specialty",
    title_zh: "晦庵河道屋",
    title_ja: "晦庵河道屋",
    romaji: "Misokaan Kawamichiya",
    summary_zh:
      "宝暦元年(1751 年継承、河道屋本家は寛永年間 1624-1644 創業) — 京都蕎麦の名門河道屋から派生、「芳香炉」と呼ばれる京都独自の鍋蕎麦を考案。1 人前小鍋に蕎麦・蝦・鶏・湯葉・しいたけ・京野菜を入れて卓上で煮込む、京都の冬の代表的なごちそう。本店は寺町二条、書斎風の数寄屋造で文人が好んだ静謐な空間。",
    content_md:
      "- 地址:京都市中京区夷川通柳馬場東入ル(地下鉄東西線「京都市役所前」駅徒歩 5 分)\n- 創業:寛永年間(1624-1644)— 河道屋本家として、晦庵分家は宝暦元年(1751)\n- 営業:11:30-19:00(LO 18:00)\n- 公休:木曜\n- 招牌:**芳香炉(ほうこうろ)** ¥3,300(1 人前小鍋蕎麦)・蕎麦御膳 ¥2,500・蕎麦寿司 ¥1,800\n- 「芳香炉」:晦庵河道屋オリジナル、1 人 1 鍋の卓上鍋蕎麦、海老・鶏・湯葉・しいたけ・春菊・京野菜入り\n- 数寄屋造:江戸後期の本館、書斎・茶室・廊下が文人好みの落着き\n- 河道屋系譜:河道屋本家(寛永)→ 河道屋養老(1762)→ 晦庵河道屋(1751 派生)、京都蕎麦の三家\n- 蕎麦の特徴:石臼挽きの強い香り、つけ汁は鰹本枯節 + 利尻昆布の濃口\n- 文学:三島由紀夫『金閣寺』『豊饒の海』執筆中の馴染、夏目漱石も訪れた\n- 蕎麦寿司:細巻きに刺身を巻いた京都独特、〆の一品\n- 当主:9 代目森田時雄氏\n- 京都駅から:バス 4・17・205 系統「河原町二条」徒歩 4 分(計 18 分)\n- 価格帯:¥2,500-5,000、芳香炉単品 ¥3,300\n- 予約:夕食は 1 週間前推奨\n- 2026-04 人工查核",
