    summary_zh:
      "昭和 15 年(1940)創業、**錦市場の代表的京漬物店**。約 50 種類の京漬物を提供、すべて京都産野菜 + 自家製味噌・米麹・酢で漬込。「**しば漬**」(大原産・赤紫蘇)・「**すぐき**」(上賀茂産・乳酸発酵)・「**千枚漬**」(聖護院かぶら・冬限定)が京都三大漬物として揃う唯一の店、観光客にも親しい量り売り。",
    content_md:
      "- 地址:京都市中京区錦小路通柳馬場西入ル中魚屋町480(阪急「河原町」駅徒歩 5 分)\n- 創業:昭和 15 年(1940)\n- 営業:10:00-18:30(無休)\n- 招牌:**京の三大漬物**(しば漬・すぐき・千枚漬)+ 茄子漬・大根漬・きゅうり浅漬・梅漬\n- **しば漬(柴漬)**:大原産茄子・きゅうり・赤紫蘇 + 塩で 1 ヶ月発酵、起源は平安期建礼門院\n- **すぐき**:上賀茂神社近辺の特産すぐき菜 + 塩のみで乳酸発酵、京都市指定無形文化財に近い扱い\n- **千枚漬**:聖護院かぶらを薄切り 1mm + 昆布 + 唐辛子、11 月-2 月限定の冬の風物詩\n- 京野菜:聖護院かぶら・賀茂茄子・伏見唐辛子・九条ねぎ・海老芋を季節限定で漬込\n- 自家製味噌:創業当時からの味噌蔵、米麹で漬床を作る伝統\n- 試食:全種類試食可、量り売り(100g から)で観光客にも便利\n- 量り売り:しば漬 100g ¥430・すぐき 100g ¥520・千枚漬 100g ¥520\n- 真空パック:お土産用、賞味期限 2-4 週間、東京便にも便利\n- 観光連動:錦市場散策の中心、有次 → 打田 → 鳥次郎 → 三木鶏卵で京の台所一周\n- 京都駅から:バス 4・17・205 系統「四条河原町」徒歩 5 分(計 18 分)\n- 価格帯:¥430-2,800、お土産セット ¥1,500-5,000\n- 2026-04 人工查核(打田漬物官網)",
