    romaji: "Kawamichiya Yōrō",
    summary_zh:
      "宝暦 12 年(1762)創業、河道屋本家から派生した京蕎麦の中核店。**「養老蕎麦」**(山芋とろろ + 鶉卵 + 海苔)は江戸期の養生食として考案、健康志向の京都人に愛された。本店は寺町二条、河道屋本家・晦庵河道屋と並ぶ京蕎麦の「河道屋三家」、それぞれ独自の名物を持つ稀有な系譜。",
    content_md:
      "- 地址:京都市中京区寺町通二条上ル要法寺前町729(地下鉄東西線「京都市役所前」駅徒歩 5 分)\n- 創業:宝暦 12 年(1762)— 江戸中期、河道屋本家からの分家\n- 営業:11:00-19:00(LO 18:30)\n- 公休:水曜\n- 招牌:**養老蕎麦** ¥1,650(山芋とろろ + 鶉卵 + 海苔 + 葱)・**鴨せいろ** ¥1,800・蕎麦寿司 ¥1,400\n- 「養老蕎麦」起源:江戸期の養生食、岐阜県養老の滝伝説と山芋の滋養を結びつけた京都解釈\n- 河道屋系譜:寛永年間 河道屋本家 → 1751 晦庵河道屋 → 1762 養老、京蕎麦の「河道屋三家」\n- 蕎麦特徴:石臼挽き、二八蕎麦(蕎麦粉 8:小麦粉 2)の伝統\n- 数寄屋造:江戸後期の本館、寺町通の落着いた古都風情\n- 寺町通老舗:一保堂(茶)・大文字屋(古書)・松好堂(扇)と組合せ散策\n- 蕎麦汁:鰹本枯節 + 利尻昆布の濃口、蕎麦湯で締め最後\n- 当主:9 代目森田氏(晦庵と兄弟経営)\n- 京都駅から:バス 4・17・205 系統「河原町二条」徒歩 4 分(計 18 分)\n- 価格帯:¥1,400-2,500\n- 2026-04 人工查核",
