      "昭和 46 年(1971)創業、**鶏白湯「こってり」スープの創始**、全国 230 店舗超のチェーン本店。北白川総本店は京都北部、屋台から始まった創業者・木村勉氏の最初の店。**「こってり」「あっさり」**の二択で全国に名を轟かせた、京都発のラーメンチェーン最高傑作。",
    content_md:
      "- 地址:京都市左京区一乗寺池田町30(叡山電鉄「一乗寺」駅徒歩 5 分)\n- 創業:昭和 46 年(1971)— 北白川の屋台「天下一品」から発祥\n- 営業:11:00-翌 1:00\n- 公休:無休\n- 招牌:**こってり** ¥830・**あっさり** ¥830・餃子 ¥350・チャーシューメン ¥1,180\n- 「こってり」:鶏ガラ + 野菜を 12 時間以上煮込んだドロドロスープ、創業者木村勉氏の発明\n- 「あっさり」:鶏ガラ + 醤油の透明スープ、こってり苦手向け\n- 創業者:木村勉氏(故)、屋台時代から「天下一」を目指した\n- 全国展開:230 店舗超、台湾・香港・米国にも進出、京都発のラーメンチェーン最大\n- 「こ」マーク:店舗の暖簾に大きな「こ」、こってり推奨の象徴\n- 限定品:総本店オリジナル「特撰こってり」(濃度 1.5 倍)\n- 北白川:ますたに本店から徒歩 8 分、京ラーメン散策で両方訪問可\n- 京都駅から:バス 17 系統「上終町京都造形芸大前」徒歩 5 分 / 叡山電鉄推奨(計 35 分)\n- 価格帯:¥830-1,500\n- 「こってりの日」毎月 1 日:こってりラーメン無料券配布(店舗による)\n- 2026-04 人工查核(天下一品官網)",
