    title_zh: "貴船 右源太(川床料理)",
    title_ja: "貴船 右源太",
    romaji: "Kibune Ugenta",
    summary_zh:
      "貞享元年(1684)創業、340 年余の貴船川床料理の代表。**標高 250m 山中、貴船川の真上**に設けた川床は鴨川納涼床より涼しく、5-9 月限定。鮎・鯉・鱧・湯葉・京野菜の懐石、川面までの距離 50cm で水の音と冷気を感じる。貴船神社参拝・京都市内 5°C 涼しい避暑、夏の京都の隠れ聖地。",
    content_md:
      "- 地址:京都市左京区鞍馬貴船町76(京阪「出町柳」乗換 叡山電鉄「貴船口」駅 + バス約 5 分)\n- 創業:貞享元年(1684)— 江戸初期\n- 営業:5-9 月のみ・11:00-19:00(LO 17:30)\n- 季節限定:川床は **5 月 1 日〜9 月 30 日**、それ以外は屋内営業\n- 招牌:**川床懐石** ¥10,000-20,000(7 品コース)・**鮎の塩焼き** ¥1,650・流しそうめん ¥1,650\n- 標高 250m:京都市内より 5°C 涼しい、夏の真昼でも 25°C 程度\n- 川床の高さ:川面から 50cm、足で水触れ可能、水の音 + 冷気 + 木陰\n- 鮎:6-8 月の天然鮎、貴船川 + 鴨川源流\n- 流しそうめん:夏休み子連れ向け、家族対応\n- 当主:14 代目右源太(現役)\n- 貴船神社:店から徒歩 8 分、水神「高龗神」、縁結びでも有名\n- 鞍馬寺:1 駅先の鞍馬駅、義経修行の伝説、半日コース可\n- 雨対策:小雨は屋根で対応、大雨・増水で閉床\n- 京都駅から:地下鉄 + 京阪 + 叡山電鉄 + バス、計 70 分(京都最遠の食事処の一つ)\n- 予約:必須、夏休みは **3 ヶ月前**\n- 価格帯:¥10,000-25,000、川床体験プレミア\n- 2026-04 人工查核(右源太官網)",
