    romaji: "Kyō no Hamo Ryōri",
    summary_zh:
      "**京都の夏の魚の代名詞「鱧」**(ハモ)、6-8 月の祇園祭シーズンに最盛期。骨切り職人技 + 梅肉 + 出汁の組合せが京懐石の夏定番。瓢亭・菊乃井・和久傳など主要料亭が **6 月-8 月限定**で鱧懐石コースを出す京都料理文化の頂点。一人 ¥15,000-30,000 の夏限定贅沢、祇園祭 7/17 山鉾巡行と組合せ「鱧祭(はも祭)」と呼ばれる京の風物詩。",
    content_md:
      "- 季節:6 月初〜8 月末、ピークは祇園祭(7 月)\n- 鱧(はも):うなぎ目鱧科、瀬戸内海・若狭湾の海鮮、3-4kg まで成長する大型海鱧\n- 「骨切り」:1cm に 25 本の包丁を入れる職人技、料亭仕入時は前職人の確認必須\n- 主要食法:**鱧落とし(梅肉)・鱧しゃぶ・鱧の天ぷら・鱧寿司・鱧の照焼き・鱧椀**\n- 提供主要店:瓢亭・菊乃井露庵 / 本店・和久傳・木乃婦・萬亀楼・桜田\n- 価格:鱧懐石 1 人 ¥15,000-30,000(料亭による)、半月コースで全体験可能\n- 「鱧祭」:祇園祭(7/14-31)期間、京都料亭が一斉に鱧コースを出す\n- 始まり:鎌倉期から食され、室町期に骨切り技術が確立、江戸期に料亭文化と結合\n- 鱧と京都:京都は海なし都市だが、若狭湾 + 瀬戸内海から早朝運搬の伝統、一年中の代用品とも\n- 体験コース:7 月中旬の祇園祭観覧 + 鱧懐石、京都旅行の定番夏プラン\n- 予約:祇園祭時期は 3 ヶ月前、それ以外は 2 週間前\n- 価格帯:単品 ¥3,000-8,000 / コース ¥15,000-30,000\n- 推奨店(初訪向け):菊乃井露庵(¥11,000 から)・和久傳系列\n- 2026-04 人工查核(京都府料理組合公式)",
