    title_zh: "末廣 鯖姿寿司本店",
    title_ja: "末廣",
    romaji: "Suehiro",
    summary_zh:
      "明治 26 年(1893)創業、120 年余の鯖寿司老舗。**いづう・いづ重に並ぶ京都鯖寿司三大店**。鴨川西岸・四条富小路、いづうの分家から派生した独立系譜。「**昆布巻鯖寿司**」(羅臼昆布で巻く)が独自、若狭鯖の脂と昆布の旨味の組合せ、お土産としては最も持ちが良い(常温 24h・冷蔵 36h)。",
