    romaji: "Ichimonjiya Wasuke",
    summary_zh:
      "**長保 2 年(1000 年)創業**、**1,025 年の日本最古飲食店候補**。今宮神社東門前、平安中期から続く「あぶり餅」(炭火炙り焼餅 + 白味噌だれ)を 25 代に渡って継承。京都府公式に「現存日本最古の和菓子店・飲食業」として記録。源氏物語・宇治拾遺物語にも記述があり、京都食文化の最古層を体現する稀有な存在、文化財・無形文化遺産級。",
    content_md:
      "- 地址:京都市北区紫野今宮町69(今宮神社東門前、地下鉄烏丸線「北大路」駅 + バス約 7 分)\n- 創業:**長保 2 年(1000 年)— 平安中期**、25 代継承\n- 営業:10:00-17:00\n- 公休:水曜(祝日翌日休)\n- 招牌:**あぶり餅 1 人前 ¥600**(炭火炙り親指大餅 11-13 串 + 白味噌だれ)\n- 「あぶり餅」:小さな餅を竹串に刺し炭火で炙り、白味噌・砂糖・きな粉のたれをつける、平安期からの素朴な菓子\n- 25 代継承:現当主は長谷川氏、1000 年連続女系家族経営\n- 「現存日本最古の飲食店候補」:京都府文化財記録に明記、世界でも稀な歴史継承例\n- 隣接「飾屋」(かざりや)1648:同じあぶり餅、向かい合って 400 年並存、二軒競合の風物詩\n- 今宮神社:疫病退散・玉の輿祈願、平安期創建、参道(あぶり餅小路)の風情\n- 食法:1 串ずつ手で取って食べる、白味噌だれの濃さ + 炭火の香ばしさ\n- 文学:源氏物語・宇治拾遺物語にもあぶり餅の記述、平安期から続く食文化\n- 持ち帰り:不可、店内で焼立てを食べる以外なし\n- 待ち時間:平日 30 分、休日 1-2 時間\n- 京都駅から:バス 206 系統「今宮神社前」徒歩 1 分(計 35 分)\n- 価格帯:¥600(1 人前で十分、二人なら 2 人前 ¥1,200)\n- 観光連動:大徳寺 + 今宮神社 + 一文字屋・飾屋、京都最古散策コース\n- 2026-04 人工查核(京都府文化財記録 + 一文字屋公式)",
