    title_ja: "角屋",
    romaji: "Sumiya",
    summary_zh:
      "**寛永 18 年(1641)創業**、384 年!**現存唯一の「揚屋」(あげや・遊郭高級料亭)、国指定重要文化財**。江戸期遊郭・嶋原(京都最古花街・1640 年公認)の頂点に立つ高級料亭兼料理茶屋として営業、新撰組・西郷隆盛・幕末志士の宴会記録が残る。1986 年から飲食営業終了し**博物館「角屋もてなしの文化美術館」**として公開、桂川治頼の襖絵・与謝蕪村の画を所蔵、京文化の生きた遺産。",
    content_md:
      "- 地址:京都市下京区西新屋敷揚屋町32(JR「梅小路京都西」駅徒歩 7 分)\n- 創業:寛永 18 年(1641)— 江戸初期、嶋原遊郭公認年(1640)直後\n- 現状:**博物館として公開**(1986 年から飲食営業終了)、入館料 ¥1,000\n- 開館時間:10:00-16:00(LO 15:30)\n- 休館:月曜・年末年始\n- **国指定重要文化財**(1952 年指定):本館・主屋・庭園すべて保存\n- 「揚屋」:江戸期遊郭の最高級料理茶屋、太夫(花魁の頂点)を呼んで遊宴する場\n- 嶋原:京都最古公認花街(1640)、室町期から続く花街文化、現代の祇園・上七軒・宮川町・先斗町・島原 五花街の最古\n- 文化人客:新撰組(土方歳三・近藤勇)・西郷隆盛・桂小五郎の宴会記録\n- **桂川治頼襖絵**:江戸後期の画家、本館部屋の襖が現存\n- **与謝蕪村**:江戸後期の俳人・画家、角屋に滞在し襖絵を残した\n- 大広間「松の間」:200 畳、太夫と客が遊ぶ大広間、現存\n- 揚屋料理復元:特別公開時に再現可、要事前予約\n- 観光連動:嶋原大門(花街門)・島原住吉神社・京都鉄道博物館と組合せ\n- 京都駅から:JR 嵯峨野線「梅小路京都西」徒歩 7 分(計 12 分)\n- 価格帯:博物館入館 ¥1,000、特別公開時の料理体験 ¥10,000+\n- 文化的意義:**現存唯一の揚屋建築**、京都遊郭文化を物理的に体験できる稀有の場\n- 2026-04 人工查核(角屋もてなしの文化美術館 + 京都府文化財記録)",
