async function main() {
  if (rows.length === 0) {
    console.log("[kyoto-food] 尚無條目,等下一批 patch");
    return;
  }

  console.log(`[kyoto-food] ${rows.length} 筆 ${DRY ? "(dry-run)" : ""}`);

  if (DRY) {
    const bySub = new Map<string, number>();
    for (const r of rows) bySub.set(r.sub_type, (bySub.get(r.sub_type) ?? 0) + 1);
    for (const [k, v] of [...bySub.entries()].sort()) {
      console.log(`  ${k.padEnd(20)} ${v}`);
    }
    return;
  }

  const sb = createAdminClient();
  const CHUNK = 50;
  let written = 0;
  for (let i = 0; i < rows.length; i += CHUNK) {
    const batch = rows.slice(i, i + CHUNK);
    const { error } = await sb.from("japan_entries").upsert(batch, {
      onConflict: "slug",
    });
    if (error) {
      console.error("[kyoto-food] upsert failed:", error);
      process.exit(1);
    }
    written += batch.length;
    process.stdout.write(`\r[kyoto-food] upsert: ${written}/${rows.length}`);
  }
  process.stdout.write("\n");
  console.log(`[kyoto-food] Done — ${written} rows.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
